from cryptography.hazmat.primitives import hashes
data = b'x'*(20000*1024)
def ref():
    d = hashes.Hash(hashes.SHA256())
    d.update(data)
    return d.finalize()
def hl():
    return hashlib.sha256(data).digest()
for f in (ref, hl):
    for _ in range(5): f()
    ts=[]
    for _ in range(30):
        t0=time.perf_counter_ns(); f(); ts.append(time.perf_counter_ns()-t0)
    print(f.__name__, statistics.median(ts)/1e6)
# measure just update vs finalize
