for _ in range(5):
    d.update(data); d.finalize()
ts=[]
for _ in range(30):
    t0=time.perf_counter_ns(); d.update(data); ts.append(time.perf_counter_ns()-t0)
print('update only', statistics.median(ts)/1e6)
